export function getProductBySlug(slug: string): Product | undefined {
  return catalog.find((p) => p.slug === slug);
}

export function getProductByCode(code: string): Product | undefined {
  const norm = code.trim().toLowerCase();
  return catalog.find((p) => p.code.toLowerCase().includes(norm));
}

export function getProductsByCategory(categorySlug: string): Product[] {
  return catalog.filter((p) => p.categorySlug === categorySlug);
}

export function getProductsBySubcategory(subcategorySlug: string): Product[] {
  return catalog.filter((p) => p.subcategorySlug === subcategorySlug);
}

export function getFeaturedProducts(): Product[] {
  return catalog.filter((p) => p.featured);
}
